mkdir -p /app/output && cat > /app/output/styles.css <<'EOF'
:root {
  --bg: #f5f5f7;
  --surface: #ffffff;
  --text: #1d1d1f;
  --muted: #6e6e73;
  --link: #0066cc;
  --border: #d2d2d7;
  --radius: 22px;
  --shadow: 0 6px 24px rgba(0, 0, 0, 0.06);
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.4;
}
a { color: var(--link); text-decoration: none; }
a:hover { text-decoration: underline; }
.container { width: min(1200px, 92vw); margin: 0 auto; }
.topbar {
  position: sticky; top: 0; z-index: 20;
  backdrop-filter: blur(10px);
  background: rgba(245,245,247,0.85);
  border-bottom: 1px solid #e6e6eb;
}
.topnav {
  display: flex; align-items: center; justify-content: space-between;
  height: 52px; font-size: 14px;
}
.brand { font-weight: 700; letter-spacing: .2px; }
.navlinks { display: flex; gap: 20px; overflow-x: auto; }
.navlinks a { color: var(--text); white-space: nowrap; }
.hero {
  text-align: center; padding: 64px 0 38px;
}
.hero h1 { margin: 0; font-size: clamp(38px, 7vw, 56px); line-height: 1.05; }
.hero p { margin: 14px auto 0; color: var(--muted); font-size: clamp(18px, 2vw, 24px); max-width: 760px; }
.section { padding: 28px 0 52px; }
.section h2 { font-size: clamp(28px,4vw,42px); margin: 0 0 16px; }
.section .sub { color: var(--muted); margin-bottom: 18px; }
.grid-heroes {
  display: grid; gap: 16px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.tile {
  border-radius: var(--radius);
  min-height: 380px;
  padding: 34px;
  position: relative;
  overflow: hidden;
  background: var(--surface);
  box-shadow: var(--shadow);
}
.tile::after {
  content: "";
  position: absolute;
  right: -70px; bottom: -80px;
  width: 280px; height: 280px;
  border-radius: 50%;
  background: radial-gradient(circle at center, rgba(255,255,255,.65), rgba(255,255,255,0));
}
.tile.cool { background: linear-gradient(135deg, #f8fbff, #edf4ff); }
.tile.warm { background: linear-gradient(135deg, #fffaf5, #fef1e7); }
.tile.neutral { background: linear-gradient(135deg, #f7f7fa, #efeff4); }
.tile .image-area {
  height: 170px; border-radius: 18px;
  margin-bottom: 22px;
  background: linear-gradient(145deg, #fff, #e9e9ef);
  display: grid; place-items: center;
  color: #8d8d96; font-size: 13px; text-transform: uppercase; letter-spacing: .12em;
}
.tile h3 { font-size: 32px; margin: 0; }
.tile p { color: var(--muted); margin: 8px 0 14px; }
.dual-cta { display: flex; gap: 14px; flex-wrap: wrap; }
.carousel-wrap { position: relative; }
.carousel-track {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(260px, 320px);
  gap: 16px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding-bottom: 6px;
  scrollbar-width: none;
}
.carousel-track::-webkit-scrollbar { display: none; }
.card {
  scroll-snap-align: start;
  border-radius: 18px;
  background: var(--surface);
  padding: 20px;
  box-shadow: var(--shadow);
  min-height: 210px;
}
.card .media {
  height: 110px;
  border-radius: 14px;
  margin-bottom: 14px;
  background: linear-gradient(135deg,#fdfdff,#ececf3);
  display: grid; place-items: center;
  color: #9d9da6; font-size: 12px; text-transform: uppercase; letter-spacing: .11em;
}
.card h4 { margin: 0; font-size: 22px; }
.card .meta { color: var(--muted); margin: 7px 0; }
.card .price { font-weight: 600; margin-top: 6px; }
.carousel-nav {
  position: absolute; right: 0; top: -52px;
  display: flex; gap: 8px;
}
.arrow {
  border: none; width: 36px; height: 36px;
  border-radius: 999px;
  background: #e9e9ee; color: #3a3a40;
  font-size: 18px; cursor: pointer;
}
.tabs { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 4px; }
.tab {
  border: 1px solid var(--border); background: #fff; color: #333;
  border-radius: 999px; padding: 9px 16px; cursor: pointer; white-space: nowrap;
}
.tab.active { background: #1d1d1f; color: #fff; border-color: #1d1d1f; }
.tab-panel { margin-top: 18px; }
.sticky-subnav {
  position: sticky; top: 52px; z-index: 12;
  background: rgba(245,245,247,0.95);
  border-top: 1px solid #e5e5ea;
  border-bottom: 1px solid #e5e5ea;
}
.subnav-inner { display: flex; gap: 16px; overflow-x: auto; padding: 12px 0; }
.subnav-inner a { color: #404046; white-space: nowrap; font-size: 14px; }
.quick-links { display: flex; flex-wrap: wrap; gap: 10px; }
.quick-links a {
  background: #fff; border: 1px solid var(--border);
  padding: 10px 14px; border-radius: 999px; color: #333;
}
.footer {
  margin-top: 56px;
  background: #f0f0f2;
  border-top: 1px solid #dfdfe3;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px; padding: 30px 0;
}
.footer h5 { margin: 0 0 10px; font-size: 14px; }
.footer ul { list-style: none; padding: 0; margin: 0; }
.footer li { margin: 8px 0; color: #4b4b52; font-size: 13px; }
.acc-btn { display: none; }
@media (max-width: 1000px) {
  .grid-heroes { grid-template-columns: 1fr; }
}
@media (max-width: 760px) {
  .footer-grid { display: block; padding: 14px 0; }
  .footer-section { border-bottom: 1px solid #dbdbe0; }
  .acc-btn {
    width: 100%; display: flex; justify-content: space-between; align-items: center;
    padding: 14px 0; border: none; background: none; font-size: 15px; cursor: pointer;
  }
  .footer-section ul { display: none; padding-bottom: 12px; }
  .footer-section.open ul { display: block; }
}
EOF

cat > /app/output/app.js <<'EOF'
(function(){
  document.querySelectorAll('[data-carousel]').forEach((wrap) => {
    const track = wrap.querySelector('.carousel-track');
    const prev = wrap.querySelector('[data-prev]');
    const next = wrap.querySelector('[data-next]');
    if (!track) return;
    const move = () => Math.max(280, Math.floor(track.clientWidth * 0.88));
    prev && prev.addEventListener('click', () => track.scrollBy({left: -move(), behavior: 'smooth'}));
    next && next.addEventListener('click', () => track.scrollBy({left: move(), behavior: 'smooth'}));
  });

  document.querySelectorAll('[data-tabs]').forEach((tabsWrap) => {
    const tabs = tabsWrap.querySelectorAll('[role="tab"]');
    const panels = tabsWrap.querySelectorAll('[role="tabpanel"]');
    const activate = (target) => {
      tabs.forEach(t => {
        const on = t.dataset.tab === target;
        t.classList.toggle('active', on);
        t.setAttribute('aria-selected', on ? 'true' : 'false');
      });
      panels.forEach(p => p.hidden = p.dataset.panel !== target);
    };
    tabs.forEach(tab => tab.addEventListener('click', () => activate(tab.dataset.tab)));
    if (tabs[0]) activate(tabs[0].dataset.tab);
  });

  document.querySelectorAll('[data-footer-accordion] .footer-section').forEach((section) => {
    const btn = section.querySelector('.acc-btn');
    if (!btn) return;
    btn.addEventListener('click', () => section.classList.toggle('open'));
  });
})();
EOF

